"""Re-run the Qwen2.5-Coder-32B API arm of nl2sql-onprem-bench through OpenRouter.

Why: in the original API run 508/1534 completions hit max_tokens=1024 mid-prose and
were scored wrong. Same prompts, same harness, greedy; only max_tokens is raised to
4096, the embedder is loaded once before the thread pool (fixes the meta-tensor
race), and the serving provider of every call is recorded.
Also re-scores every released jsonl with the official BIRD comparison (set equality).
"""
import collections, json, os, subprocess, sys, threading, time, zipfile, glob

W = "/kaggle/working"
REPO = f"{W}/nl2sql-onprem-bench"
OUT = f"{W}/sql_rerun"
os.makedirs(OUT, exist_ok=True)

def sh(c):
    print("$", c, flush=True); subprocess.run(c, shell=True, check=True)

if not os.path.isdir(REPO):
    sh(f"git clone -q https://github.com/beskvladimir-create/nl2sql-onprem-bench.git {REPO}")
sh(f"cd {REPO} && git log --oneline -1")
sh(f"{sys.executable} -m pip install -q -e {REPO}[emb] func-timeout")

# ---- BIRD dev ---------------------------------------------------------------
BIRD = f"{W}/bird"
if not os.path.isfile(f"{BIRD}/dev.json"):
    os.makedirs(BIRD, exist_ok=True)
    sh(f"cd {W} && wget -q -O dev.zip https://bird-bench.oss-cn-beijing.aliyuncs.com/dev.zip")
    sh(f"cd {W} && unzip -q -o dev.zip -d bird_raw && ls -R bird_raw | head -20")
    dj = glob.glob(f"{W}/bird_raw/**/dev.json", recursive=True)[0]
    d = os.path.dirname(dj)
    sh(f"cp '{dj}' {BIRD}/dev.json")
    inner = glob.glob(f"{d}/dev_databases.zip")
    if inner:
        sh(f"cd {BIRD} && unzip -q -o '{inner[0]}'")
    else:
        sh(f"cp -r '{d}/dev_databases' {BIRD}/")
    sh(f"ls {BIRD}/dev_databases | head; ls {BIRD}/dev_databases | wc -l")
# ---- harness fixes (read-only databases, official set comparison, extract_sql, embedder lock) ----
import base64 as _b64
_PATCH = {
    "evaluator.py": "",
    "pipeline.py": "",
    "schema.py": "",
}
for _f, _c in _PATCH.items():
    open(f"{REPO}/src/nl2sql_bench/{_f}", "wb").write(_b64.b64decode(_c))
print("patched harness files:", list(_PATCH))
sys.path.insert(0, f"{REPO}/src")

from kaggle_secrets import UserSecretsClient
KEY = UserSecretsClient().get_secret("OPENROUTER_API_KEY")

from nl2sql_bench import model_client as mc, schema as sc
from nl2sql_bench.runner import run

# load the embedder once, in the main thread (the original run crashed 61 items on a race)
sc._get_embedder()
# (the patched schema.py serializes embedder load/encode with its own lock)

PROVIDERS = collections.Counter()
FINISH = collections.Counter()

class ORClient(mc.ModelClient):
    def complete(self, prompt, temperature=None):
        t0 = time.perf_counter()
        for attempt in range(5):
            try:
                resp = self._client.chat.completions.create(
                    model=self.model,
                    messages=[{"role": "user", "content": prompt}],
                    temperature=self.temperature if temperature is None else temperature,
                    max_tokens=self.max_tokens,
                )
                break
            except Exception as e:
                if attempt == 4:
                    raise
                time.sleep(5 * (attempt + 1))
        dt = time.perf_counter() - t0
        PROVIDERS[getattr(resp, "provider", None) or (resp.model_extra or {}).get("provider")] += 1
        FINISH[resp.choices[0].finish_reason] += 1
        u = resp.usage
        return mc.Completion(text=resp.choices[0].message.content or "",
                             prompt_tokens=getattr(u, "prompt_tokens", 0),
                             completion_tokens=getattr(u, "completion_tokens", 0),
                             latency_s=dt)

client = ORClient(model="qwen/qwen-2.5-coder-32b-instruct",
                  base_url="https://openrouter.ai/api/v1", api_key=KEY, max_tokens=4096)

STAGES = [
    ("base", dict(schema_link=False, self_correct=False, self_consistency=False)),
    ("link", dict(schema_link=True, self_correct=False, self_consistency=False)),
    ("link_emb", dict(schema_link_emb=True, emb_top_k=6, self_correct=False, self_consistency=False)),
    ("correct", dict(schema_link=False, self_correct=True, self_consistency=False)),
    ("link_emb_correct", dict(schema_link_emb=True, emb_top_k=6, self_correct=True, self_consistency=False)),
]
LIMIT = 8 if os.environ.get("KAGGLE_KERNEL_RUN_TYPE") == "Interactive" else None
print("run type", os.environ.get("KAGGLE_KERNEL_RUN_TYPE"), "LIMIT", LIMIT)
meta = {}
for name, flags in STAGES:
    PROVIDERS.clear(); FINISH.clear()
    out = f"{OUT}/qwen25-coder-32b-or.{name}.jsonl"
    s = run(BIRD, client, out, limit=LIMIT, concurrency=16, **flags)
    s["providers"] = dict(PROVIDERS); s["finish_reasons"] = dict(FINISH); s["max_tokens"] = 4096
    json.dump(s, open(out.replace(".jsonl", ".summary.json"), "w"), indent=2, default=str)
    print(name, s["ex_accuracy"], dict(PROVIDERS), dict(FINISH), flush=True)
    meta[name] = s

json.dump(meta, open(f"{OUT}/rerun_meta.json", "w"), indent=2, default=str)
# official BIRD set comparison for the re-run files
import sqlite3
from func_timeout import func_timeout
def _rows(db, sql):
    c = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    try:
        return c.execute(sql).fetchall()
    finally:
        c.close()
def _ex(db, sql):
    try:
        return func_timeout(30, _rows, args=(db, sql))
    except Exception:
        return None
# gold SQL used by the original runs (BIRD dev release they were scored against)
OLD_GOLD = {json.loads(l)["qid"]: json.loads(l)["gold_sql"] for l in open(f"{REPO}/results/qwen25-coder-32b-api.base.jsonl")}
off = {}
for f in sorted(glob.glob(f"{OUT}/*.jsonl")):
    recs = [json.loads(l) for l in open(f)]
    n_gold_diff = sum(1 for r in recs if OLD_GOLD.get(r["qid"]) != r["gold_sql"])
    cnt = collections.Counter()
    per = []
    for r in recs:
        db = f"{BIRD}/dev_databases/{r['db_id']}/{r['db_id']}.sqlite"
        p = _ex(db, r["pred_sql"]) if r.get("pred_sql") else None
        row = {"qid": r["qid"]}
        for tag, gs in (("new", r["gold_sql"]), ("old", OLD_GOLD.get(r["qid"], r["gold_sql"]))):
            g = _ex(db, gs)
            ok_m = g is not None and p is not None and sorted(map(repr, p)) == sorted(map(repr, g))
            ok_s = g is not None and p is not None and set(p) == set(g)
            cnt[f"{tag}_multiset"] += ok_m; cnt[f"{tag}_set"] += ok_s
            row[f"{tag}_multiset"] = bool(ok_m); row[f"{tag}_set"] = bool(ok_s)
        per.append(row)
    json.dump(per, open(f.replace(".jsonl", ".rescored.json"), "w"))
    off[os.path.basename(f)] = {k: v / len(recs) for k, v in cnt.items()} | {"n": len(recs), "gold_differs_from_original": n_gold_diff}
    print(os.path.basename(f), off[os.path.basename(f)], flush=True)
json.dump(off, open(f"{OUT}/official_set_eval.json", "w"), indent=2)
sh(f"cd {W} && zip -q -r sql_rerun.zip sql_rerun")
print("DONE")
